cards.solution:
const hargaRoti: number = 8000;
const jumlahRoti: number = 3;
const hargaSusu: number = 6500;
const jumlahSusu: number = 2;
const total: number = hargaRoti * jumlahRoti + hargaSusu * jumlahSusu;
const diAtas30Ribu: boolean = total > 30000;
console.log("Total:", total);
console.log("Di atas 30 ribu:", diAtas30Ribu);
